"""install_pydantic.py

Reads JSON schemas from objectiveai-json-schema/ and generates Pydantic models
in objectiveai-py/objectiveai/ with proper imports and __init__.py barrel exports.

This is the Python equivalent of objectiveai-js/scripts/install-zod.cjs.
"""

import json
import os
import re
import sys
from pathlib import Path

SCHEMA_DIR = Path(__file__).resolve().parent.parent.parent / "objectiveai-json-schema"
SRC_DIR = Path(__file__).resolve().parent.parent / "objectiveai"

GENERATED_HEADER = (
    "# THIS FILE IS AUTO-GENERATED. DO NOT EDIT.\n"
    "# Generated by scripts/install_pydantic.py from objectiveai-json-schema/.\n"
)

# Known generic prefixes — monomorphized types that should be grouped
# under the base type's file.
GENERIC_PREFIXES = [
    "functions.expression.WithExpression.",
    "agent.WithFallbacksAndCount.",
    "functions.expression.OneOrMany.",
]


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def title_to_pascal(title: str) -> str:
    """Convert a dot-separated title to PascalCase.

    "agent.Agent" → "AgentAgent"
    "agent.claude_agent_sdk.Agent" → "AgentClaudeAgentSdkAgent"
    """
    return "".join(
        s[0].upper() + s[1:] for s in re.split(r"[._]", title) if s
    )


def get_generic_base(title: str) -> str | None:
    """Return the generic base if this is a monomorphized generic, else None."""
    for prefix in GENERIC_PREFIXES:
        if title.startswith(prefix) and len(title) > len(prefix):
            return prefix.rstrip(".")
    return None


def title_to_path(title: str) -> tuple[str, str]:
    """Map a schema title to (directory, filename) relative to SRC_DIR.

    "agent.Agent" → ("agent", "agent")
    "ResponseError" → ("", "response_error")
    "functions.expression.WithExpression.string"
        → ("functions/expression", "with_expression")
    """
    generic_base = get_generic_base(title)
    if generic_base:
        parts = generic_base.split(".")
    else:
        parts = title.split(".")

    type_name = parts.pop()
    dir_path = "/".join(parts)
    file_name = _to_snake(type_name)
    return dir_path, file_name


def _to_snake(name: str) -> str:
    """Convert PascalCase or camelCase to snake_case."""
    s = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1_\2", name)
    s = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", s)
    return s.lower()


def _is_snake(name: str) -> bool:
    return name == _to_snake(name)


# ---------------------------------------------------------------------------
# JSON Schema → Python type annotation conversion
# ---------------------------------------------------------------------------


def convert_to_type(schema: dict, self_title: str, all_titles: set[str]) -> str:
    """Recursively convert a JSON schema node to a Python type annotation string.

    Self-references ($ref: "#") produce the PascalCase name of self_title,
    which works as a forward reference when `from __future__ import annotations`
    is active and the type is used as a class field annotation.
    """
    if not schema or not isinstance(schema, dict):
        return "object"

    # $ref
    if "$ref" in schema:
        ref = schema["$ref"]
        ref_title = self_title if ref == "#" else ref
        base_type = title_to_pascal(ref_title)
        if "properties" in schema:
            return base_type
        return base_type

    # const
    if "const" in schema:
        val = schema["const"]
        if isinstance(val, str):
            return f"Literal[{val!r}]"
        return f"Literal[{json.dumps(val)}]"

    # enum
    if "enum" in schema:
        literals = ", ".join(repr(v) for v in schema["enum"])
        return f"Literal[{literals}]"

    # oneOf
    if "oneOf" in schema:
        variants = [convert_to_type(v, self_title, all_titles) for v in schema["oneOf"]]
        return _union_type(variants)

    # anyOf
    if "anyOf" in schema:
        return _convert_any_of_type(schema["anyOf"], self_title, all_titles)

    # type handling
    type_ = schema.get("type")
    if isinstance(type_, list):
        parts = [_convert_single_type(t, schema, self_title, all_titles) for t in type_]
        return _union_type(parts)
    if isinstance(type_, str):
        return _convert_single_type(type_, schema, self_title, all_titles)
    if "properties" in schema:
        return _convert_single_type("object", schema, self_title, all_titles)
    return "object"


def _convert_any_of_type(any_of: list[dict], self_title: str, all_titles: set[str]) -> str:
    null_variant = next(
        (v for v in any_of if v.get("type") == "null" or v.get("type") == ["null"]),
        None,
    )
    non_null = [v for v in any_of if v is not null_variant]
    if null_variant and len(non_null) == 1:
        inner = convert_to_type(non_null[0], self_title, all_titles)
        return f"Optional[{inner}]"
    variants = [convert_to_type(v, self_title, all_titles) for v in any_of]
    return _union_type(variants)


def _convert_single_type(type_: str, schema: dict, self_title: str, all_titles: set[str]) -> str:
    if type_ == "string":
        return "str"
    if type_ in ("number", "integer"):
        if schema.get("format") in ("uint64", "int64"):
            return "int"
        if type_ == "integer":
            return "int"
        return "float"
    if type_ == "boolean":
        return "bool"
    if type_ == "null":
        return "None"
    if type_ == "array":
        if "items" in schema:
            inner = convert_to_type(schema["items"], self_title, all_titles)
            return f"list[{inner}]"
        return "list[object]"
    if type_ == "object":
        return _convert_object_type(schema, self_title, all_titles)
    return "object"


def _convert_object_type(schema: dict, self_title: str, all_titles: set[str]) -> str:
    if "properties" not in schema and schema.get("additionalProperties"):
        val_type = convert_to_type(
            schema["additionalProperties"]
            if isinstance(schema["additionalProperties"], dict)
            else {},
            self_title,
            all_titles,
        )
        return f"dict[str, {val_type}]"
    if "properties" not in schema:
        return "dict[str, object]"
    return "dict[str, object]"


def _union_type(variants: list[str]) -> str:
    seen = set()
    unique = []
    for v in variants:
        if v not in seen:
            seen.add(v)
            unique.append(v)
    if len(unique) == 1:
        return unique[0]
    return f"Union[{', '.join(unique)}]"


# ---------------------------------------------------------------------------
# JSON Schema → Pydantic model generation
# ---------------------------------------------------------------------------


def collect_refs(schema: dict | list | None, refs: set[str]) -> None:
    """Recursively collect all $ref titles from a schema."""
    if schema is None or not isinstance(schema, (dict, list)):
        return
    if isinstance(schema, list):
        for item in schema:
            collect_refs(item, refs)
        return
    if "$ref" in schema:
        if schema["$ref"] != "#":
            refs.add(schema["$ref"])
        for key, value in schema.items():
            if key != "$ref":
                collect_refs(value, refs)
        return
    for value in schema.values():
        collect_refs(value, refs)


def has_self_ref(schema: dict | list | None) -> bool:
    """Check if a schema contains a self-reference ($ref: '#')."""
    if schema is None or not isinstance(schema, (dict, list)):
        return False
    if isinstance(schema, list):
        return any(has_self_ref(s) for s in schema)
    if schema.get("$ref") == "#":
        return True
    return any(has_self_ref(v) for v in schema.values())


def _is_type_alias_schema(schema: dict) -> bool:
    """Check if a schema would generate a type alias (not a BaseModel class)."""
    if "properties" in schema:
        return False
    if schema.get("type") == "object":
        return False
    return True


def generate_model(
    title: str,
    schema: dict,
    all_titles: set[str],
    *,
    use_root_model: bool = False,
) -> tuple[str, set[str]]:
    """Generate a Pydantic model or type alias for a schema.

    If use_root_model is True, union/alias types are generated as RootModel
    subclasses instead of plain type aliases. This is required when:
    - The type has self-references ($ref: "#")
    - The type participates in an import cycle with other type alias files

    RootModel field annotations are deferred via `from __future__ import annotations`,
    so forward refs and TYPE_CHECKING guards work correctly.

    Returns (code_string, set_of_ref_titles).
    """
    refs: set[str] = set()
    pascal_name = title_to_pascal(title)

    has_properties = "properties" in schema
    has_any_of = "anyOf" in schema
    has_one_of = "oneOf" in schema
    type_ = schema.get("type")

    description = schema.get("description", "")
    safe_desc = description.replace('"""', '\\"\\"\\"') if description else ""

    # Case 1: Object with properties AND anyOf/oneOf (serde flatten)
    if has_properties and (has_any_of or has_one_of):
        code = _generate_flattened_model(title, schema, refs, all_titles, pascal_name, safe_desc)
        return code, refs

    # Case 2: Simple object with properties → Pydantic BaseModel
    if has_properties or type_ == "object":
        code = _generate_object_model(title, schema, refs, all_titles, pascal_name, safe_desc)
        return code, refs

    # Case 3: oneOf/anyOf without properties → Union type alias or RootModel
    if has_one_of or has_any_of:
        variants_schema = schema.get("oneOf") or schema.get("anyOf", [])

        # String enums (all const strings) → Literal (never needs RootModel)
        if all(
            v.get("const") is not None and isinstance(v.get("const"), str)
            for v in variants_schema
        ):
            literals = ", ".join(repr(v["const"]) for v in variants_schema)
            code = f"{pascal_name} = Literal[{literals}]"
            if safe_desc:
                code += f'\n"""{safe_desc}"""'
            code += "\n"
            return code, refs

        # Nullable union: [something, null]
        null_variant = next(
            (v for v in variants_schema if v.get("type") == "null"),
            None,
        )
        non_null = [v for v in variants_schema if v is not null_variant]

        if null_variant and len(non_null) == 1:
            inner_type = convert_to_type(non_null[0], title, all_titles)
            collect_refs(non_null[0], refs)
            if use_root_model:
                code = _make_root_model(pascal_name, safe_desc, f"Optional[{inner_type}]")
            else:
                code = f"{pascal_name} = Optional[{inner_type}]"
                if safe_desc:
                    code += f'\n"""{safe_desc}"""'
                code += "\n"
            return code, refs

        # General union
        variant_types = []
        for v in variants_schema:
            collect_refs(v, refs)
            variant_types.append(convert_to_type(v, title, all_titles))
        union_str = _union_type(variant_types)

        if use_root_model:
            code = _make_root_model(pascal_name, safe_desc, union_str)
        else:
            code = f"{pascal_name} = {union_str}"
            if safe_desc:
                code += f'\n"""{safe_desc}"""'
            code += "\n"
        return code, refs

    # Case 4: enum of strings → Literal
    if "enum" in schema:
        literals = ", ".join(repr(v) for v in schema["enum"])
        code = f"{pascal_name} = Literal[{literals}]"
        if safe_desc:
            code += f'\n"""{safe_desc}"""'
        code += "\n"
        return code, refs

    # Case 5: const
    if "const" in schema:
        val = schema["const"]
        code = f"{pascal_name} = Literal[{val!r}]"
        if safe_desc:
            code += f'\n"""{safe_desc}"""'
        code += "\n"
        return code, refs

    # Case 6: Primitive type alias
    type_str = convert_to_type(schema, title, all_titles)
    collect_refs(schema, refs)
    if use_root_model:
        code = _make_root_model(pascal_name, safe_desc, type_str)
    else:
        code = f"{pascal_name} = {type_str}"
        if safe_desc:
            code += f'\n"""{safe_desc}"""'
        code += "\n"
    return code, refs


def _make_root_model(pascal_name: str, safe_desc: str, root_type: str) -> str:
    """Generate a RootModel subclass with a root field annotation."""
    lines = [f"class {pascal_name}(RootModel):"]
    if safe_desc:
        lines.append(f'    """{safe_desc}"""')
    lines.append(f"    root: {root_type}")
    return "\n".join(lines) + "\n"


def _generate_object_model(
    title: str,
    schema: dict,
    refs: set[str],
    all_titles: set[str],
    pascal_name: str,
    safe_desc: str,
) -> str:
    """Generate a Pydantic BaseModel for an object schema."""
    properties = schema.get("properties", {})
    required = set(schema.get("required", []))

    lines = [f"class {pascal_name}(BaseModel):"]
    if safe_desc:
        lines.append(f'    """{safe_desc}"""')
    if not properties:
        if schema.get("additionalProperties") is False:
            lines.append("    model_config = ConfigDict(extra='forbid')")
        else:
            lines.append("    pass")
        return "\n".join(lines) + "\n"

    if schema.get("additionalProperties") is False:
        lines.append("    model_config = ConfigDict(extra='forbid')")
        lines.append("")

    for prop_name, prop_schema in properties.items():
        collect_refs(prop_schema, refs)
        prop_type = convert_to_type(prop_schema, title, all_titles)
        field_name = _to_snake(prop_name) if not _is_snake(prop_name) else prop_name
        # Python keyword escaping
        if field_name in ("from", "type", "class", "import", "in", "is", "not", "and", "or"):
            alias = prop_name
            field_name = field_name + "_"
        else:
            alias = prop_name if prop_name != field_name else None

        is_required = prop_name in required

        if not is_required:
            default = prop_schema.get("default")
            if default is not None:
                default_repr = repr(default)
                if alias:
                    lines.append(
                        f"    {field_name}: {prop_type} = Field({default_repr}, alias={alias!r})"
                    )
                else:
                    lines.append(f"    {field_name}: {prop_type} = {default_repr}")
            else:
                if not prop_type.startswith("Optional["):
                    prop_type = f"Optional[{prop_type}]"
                if alias:
                    lines.append(
                        f"    {field_name}: {prop_type} = Field(None, alias={alias!r})"
                    )
                else:
                    lines.append(f"    {field_name}: {prop_type} = None")
        else:
            if alias:
                lines.append(
                    f"    {field_name}: {prop_type} = Field(..., alias={alias!r})"
                )
            else:
                lines.append(f"    {field_name}: {prop_type}")

    return "\n".join(lines) + "\n"


def _generate_flattened_model(
    title: str,
    schema: dict,
    refs: set[str],
    all_titles: set[str],
    pascal_name: str,
    safe_desc: str,
) -> str:
    """Generate a model for schemas with properties AND anyOf/oneOf (serde flatten).

    Serde flatten merges the inner variant's fields with the outer properties.
    We generate a BaseModel with the outer properties + extra='allow' so the
    variant fields pass through, and a _variant field typed as the union of
    anyOf types for documentation purposes. The model also stores which variant
    type it represents.
    """
    # Build the object model with extra='allow' so variant fields are accepted
    properties = schema.get("properties", {})
    required = set(schema.get("required", []))
    variants = schema.get("anyOf") or schema.get("oneOf", [])

    # Generate the model with extra='allow' to accept flattened variant fields
    lines = [f"class {pascal_name}(BaseModel):"]
    if safe_desc:
        lines.append(f'    """{safe_desc}"""')
    lines.append("    model_config = ConfigDict(extra='allow')")
    lines.append("")

    # Add the outer properties
    for prop_name, prop_schema in properties.items():
        collect_refs(prop_schema, refs)
        prop_type = convert_to_type(prop_schema, title, all_titles)
        field_name = _to_snake(prop_name) if not _is_snake(prop_name) else prop_name
        if field_name in ("from", "type", "class", "import", "in", "is", "not", "and", "or"):
            alias = prop_name
            field_name = field_name + "_"
        else:
            alias = prop_name if prop_name != field_name else None

        is_required = prop_name in required

        if not is_required:
            default = prop_schema.get("default")
            if default is not None:
                default_repr = repr(default)
                if alias:
                    lines.append(
                        f"    {field_name}: {prop_type} = Field({default_repr}, alias={alias!r})"
                    )
                else:
                    lines.append(f"    {field_name}: {prop_type} = {default_repr}")
            else:
                if not prop_type.startswith("Optional["):
                    prop_type = f"Optional[{prop_type}]"
                if alias:
                    lines.append(
                        f"    {field_name}: {prop_type} = Field(None, alias={alias!r})"
                    )
                else:
                    lines.append(f"    {field_name}: {prop_type} = None")
        else:
            if alias:
                lines.append(
                    f"    {field_name}: {prop_type} = Field(..., alias={alias!r})"
                )
            else:
                lines.append(f"    {field_name}: {prop_type}")

    return "\n".join(lines) + "\n"


# ---------------------------------------------------------------------------
# Cycle detection
# ---------------------------------------------------------------------------


def find_files_in_cycles(
    file_groups: dict[str, list],
    file_refs: dict[str, set[str]],
) -> set[str]:
    """Find all files that participate in dependency cycles."""
    files_in_cycles: set[str] = set()
    for f in file_groups:
        visited: set[str] = set()
        queue = list(file_refs.get(f, set()) - {f})
        while queue:
            v = queue.pop(0)
            if v == f:
                files_in_cycles.add(f)
                break
            if v in visited:
                continue
            visited.add(v)
            queue.extend(file_refs.get(v, set()))
    return files_in_cycles


# ---------------------------------------------------------------------------
# Clean previously generated files
# ---------------------------------------------------------------------------


def clean_generated(directory: Path) -> None:
    """Recursively delete files containing the auto-generated marker,
    then prune empty directories bottom-up."""
    if not directory.exists():
        return
    for entry in list(directory.iterdir()):
        if entry.is_dir():
            clean_generated(entry)
        elif entry.is_file() and entry.suffix == ".py":
            try:
                head = entry.read_text(encoding="utf-8")[:128]
                if "THIS FILE IS AUTO-GENERATED" in head:
                    entry.unlink()
            except (OSError, UnicodeDecodeError):
                pass
    try:
        if directory.exists() and not any(directory.iterdir()):
            directory.rmdir()
    except OSError:
        pass


def _is_generated(path: Path) -> bool:
    try:
        return "THIS FILE IS AUTO-GENERATED" in path.read_text(encoding="utf-8")[:128]
    except (OSError, UnicodeDecodeError):
        return False


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------


def main() -> None:
    clean_generated(SRC_DIR)

    # Read all schema files
    schema_files = sorted(SCHEMA_DIR.glob("*.json"))
    schemas: dict[str, dict] = {}
    for f in schema_files:
        content = json.loads(f.read_text(encoding="utf-8"))
        if "title" in content:
            schemas[content["title"]] = content

    print(f"Read {len(schemas)} schemas")

    all_titles = set(schemas.keys())

    # Group schemas by output file path
    file_groups: dict[str, list[dict]] = {}
    for title, schema in schemas.items():
        dir_path, file_name = title_to_path(title)
        file_path = f"{dir_path}/{file_name}" if dir_path else file_name
        file_groups.setdefault(file_path, []).append(
            {"title": title, "schema": schema}
        )

    print(f"Generating {len(file_groups)} .py files")

    # Build file dependency graph
    file_refs: dict[str, set[str]] = {}
    for file_path, entries in file_groups.items():
        refs: set[str] = set()
        for entry in entries:
            collect_refs(entry["schema"], refs)
        dep_files: set[str] = set()
        for ref in refs:
            ref_dir, ref_file = title_to_path(ref)
            ref_path = f"{ref_dir}/{ref_file}" if ref_dir else ref_file
            if ref_path != file_path:
                dep_files.add(ref_path)
        file_refs[file_path] = dep_files

    # Detect cycles
    files_in_cycles = find_files_in_cycles(file_groups, file_refs)
    if files_in_cycles:
        print(f"Found {len(files_in_cycles)} file(s) in dependency cycles")

    # Determine which files need RootModel for their type aliases.
    # A file needs RootModel if it's a type-alias-only file in a cycle,
    # OR if any of its schemas have self-references.
    files_needing_root_model: set[str] = set()
    for file_path, entries in file_groups.items():
        for entry in entries:
            if has_self_ref(entry["schema"]) and _is_type_alias_schema(entry["schema"]):
                files_needing_root_model.add(file_path)
                break
        if file_path in files_in_cycles:
            # Check if this file has type aliases (non-BaseModel schemas)
            has_type_alias = any(_is_type_alias_schema(e["schema"]) for e in entries)
            if has_type_alias:
                files_needing_root_model.add(file_path)

    if files_needing_root_model:
        print(f"Using RootModel for {len(files_needing_root_model)} file(s) with cyclic/self-referential type aliases")

    # Track all directories for __init__.py generation
    all_dirs: set[str] = set()

    # Generate each .py file
    for file_path, entries in file_groups.items():
        all_refs: set[str] = set()
        model_codes: list[str] = []
        file_in_cycle = file_path in files_in_cycles
        use_root_model = file_path in files_needing_root_model

        for entry in entries:
            code, refs = generate_model(
                entry["title"],
                entry["schema"],
                all_titles,
                use_root_model=use_root_model,
            )
            model_codes.append(code)
            all_refs |= refs

        # Build imports
        import_lines: list[str] = []

        full_code = "\n".join(model_codes)
        typing_imports: list[str] = []
        if "Literal[" in full_code:
            typing_imports.append("Literal")
        if "Optional[" in full_code:
            typing_imports.append("Optional")
        if "Union[" in full_code:
            typing_imports.append("Union")

        # Always add future annotations for forward reference support
        import_lines.append("from __future__ import annotations")

        if typing_imports:
            import_lines.append(f"from typing import {', '.join(sorted(typing_imports))}")

        # Determine pydantic imports
        pydantic_imports: list[str] = []
        if "BaseModel" in full_code:
            pydantic_imports.append("BaseModel")
        if "ConfigDict" in full_code:
            pydantic_imports.append("ConfigDict")
        if "Field(" in full_code:
            pydantic_imports.append("Field")
        if "RootModel" in full_code:
            pydantic_imports.append("RootModel")

        if pydantic_imports:
            import_lines.append(
                f"from pydantic import {', '.join(sorted(pydantic_imports))}"
            )

        # Group refs by their target file
        refs_by_file: dict[str, list[str]] = {}
        for ref in all_refs:
            ref_dir, ref_file = title_to_path(ref)
            ref_path = f"{ref_dir}/{ref_file}" if ref_dir else ref_file
            if ref_path == file_path:
                continue
            refs_by_file.setdefault(ref_path, []).append(ref)

        # Split imports: regular vs TYPE_CHECKING-guarded
        # All files in cycles now use classes (BaseModel or RootModel), so
        # TYPE_CHECKING guards work for all inter-cycle imports.
        regular_imports: list[str] = []
        type_checking_imports: list[str] = []

        for ref_path in sorted(refs_by_file.keys()):
            ref_titles = refs_by_file[ref_path]
            names = sorted(set(title_to_pascal(t) for t in ref_titles))
            module_path = "objectiveai." + ref_path.replace("/", ".")
            names_str = ", ".join(names)
            is_cyclic = file_in_cycle and ref_path in files_in_cycles
            if is_cyclic:
                type_checking_imports.append(
                    f"    from {module_path} import {names_str}"
                )
            else:
                regular_imports.append(f"from {module_path} import {names_str}")

        import_lines.extend(regular_imports)

        # Add TYPE_CHECKING import if needed
        if type_checking_imports:
            typing_imports.append("TYPE_CHECKING")
            # Rebuild the typing import line
            found_typing = False
            for i, line in enumerate(import_lines):
                if line.startswith("from typing import"):
                    import_lines[i] = f"from typing import {', '.join(sorted(typing_imports))}"
                    found_typing = True
                    break
            if not found_typing:
                import_lines.append(f"from typing import TYPE_CHECKING")

        # Assemble the file
        content = GENERATED_HEADER
        if import_lines:
            content += "\n".join(import_lines) + "\n"

        if type_checking_imports:
            content += "\nif TYPE_CHECKING:\n"
            content += "\n".join(type_checking_imports) + "\n"

        content += "\n\n" + "\n\n".join(model_codes) + "\n"

        # Write the file
        full_path = SRC_DIR / (file_path.replace("/", os.sep) + ".py")
        full_path.parent.mkdir(parents=True, exist_ok=True)
        full_path.write_text(content, encoding="utf-8")

        # Track directories
        parts = file_path.split("/")
        for i in range(1, len(parts)):
            all_dirs.add("/".join(parts[:i]))

    # Generate empty __init__.py files to make directories importable as packages.
    # We do NOT re-export via `from .module import *` because that triggers eager
    # loading of all sibling modules, which creates circular import chains.
    all_dirs.add("")  # root package

    for dir_path in sorted(all_dirs, key=len, reverse=True):
        abs_dir = SRC_DIR / dir_path.replace("/", os.sep) if dir_path else SRC_DIR
        if not abs_dir.exists():
            continue

        init_path = abs_dir / "__init__.py"
        if not init_path.exists() or _is_generated(init_path):
            init_path.write_text(GENERATED_HEADER, encoding="utf-8")

    print(f"Generated __init__.py for {len(all_dirs)} directories")
    print("Done!")


if __name__ == "__main__":
    main()
